#!/usr/bin/env python3
from __future__ import annotations

import argparse
import gzip
import json
import os
import shutil
import subprocess
import sys
import time
from pathlib import Path

MARKER = (
    "<!-- generated by meerai build-web.py: delete this line to keep your own edits -->"
)
OLD_MARKER = (
    "<!-- generated by meerai build-web.sh: delete this line to keep your own edits -->"
)

BOOT_JS = """import init from './app.js';
const status = document.querySelector('#status');
function fail(error) {
    status.replaceChildren();
    const logo = document.createElement('div');
    logo.className = 'logo';
    logo.textContent = 'meerai';
    const message = document.createElement('div');
    message.className = 'error';
    message.textContent = String(error);
    const hint = document.createElement('div');
    hint.className = 'hint';
    hint.textContent = 'Run `meerai` in your terminal to use the TUI.';
    status.append(logo, message, hint);
}
try {
    if (!window.__meeraiBooted) {
        window.__meeraiBooted = true;
        await init();
    }
    status.remove();
} catch (error) {
    fail(error);
    console.error(error);
}
"""

INDEX_HTML = f"""<!doctype html>
{MARKER}
<html lang="en">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="color-scheme" content="dark light">
<meta name="theme-color" content="#0b0d10">
<title>meerai</title>
<link rel="icon" href="favicon.svg" type="image/svg+xml">
<link rel="icon" href="favicon.ico" sizes="any">
<link rel="icon" type="image/png" sizes="32x32" href="favicon-32x32.png">
<link rel="icon" type="image/png" sizes="16x16" href="favicon-16x16.png">
<link rel="apple-touch-icon" sizes="180x180" href="apple-touch-icon.png">
<link rel="stylesheet" href="styles.css">
<style>
html,body{{margin:0;width:100%;height:100%;overflow:hidden;font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;background:#0a0a0a;color:#eeeeee}}
#app{{width:100%;height:100%}}
#status{{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;height:100%;padding:24px;text-align:center;box-sizing:border-box}}
.logo{{font-size:18px;font-weight:600;letter-spacing:-0.02em;color:#2dd4bf}}
.spinner{{width:18px;height:18px;border-radius:50%;border:2px solid #2a2a2a;border-top-color:#2dd4bf;animation:spin .8s linear infinite}}
.hint{{max-width:520px;font-size:13px;line-height:1.5;color:#808080}}
.error{{max-width:560px;font-size:14px;line-height:1.55;color:#e06c75}}
@keyframes spin{{to{{transform:rotate(360deg)}}}}
@media (prefers-color-scheme:light){{html,body{{background:#fafafa;color:#111111}}.hint{{color:#666666}}.spinner{{border-color:#dddddd;border-top-color:#0f766e}}.logo{{color:#0f766e}}}}
</style>
<div id="app"></div>
<div id="status"><div class="logo">meerai</div><div class="spinner"></div><div class="hint">Connecting to the local workspace…</div></div>
<script type="module" src="boot.js"></script>
</html>
"""


def parse_args(default_out: Path) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        prog="build-web.py",
        description="Build the meerai-web-client Leptos Wasm bundle.",
    )
    parser.add_argument(
        "--out", type=Path, default=default_out, help="Output directory"
    )
    parser.add_argument(
        "--opt", action="store_true", help="Run wasm-opt -Oz on release builds"
    )
    parser.add_argument("--dev", action="store_true", help="Build fast web-dev profile")
    parser.add_argument(
        "--no-html", action="store_true", help="Do not write index.html or boot.js"
    )
    parser.add_argument("--names", action="store_true", help="Keep Wasm function names")
    return parser.parse_args()


def capture(cmd: list[str]) -> str | None:
    try:
        res = subprocess.run(cmd, check=True, capture_output=True, text=True)
    except (OSError, subprocess.CalledProcessError):
        return None
    out = res.stdout.strip()
    return out or None


def resolve_cargo(env: dict[str, str]) -> str:
    if env.get("CARGO"):
        return env["CARGO"]
    rustup_cargo = capture(["rustup", "which", "cargo"])
    if rustup_cargo:
        return rustup_cargo
    cargo = shutil.which("cargo")
    if not cargo:
        sys.exit("cargo binary not found on PATH")
    return cargo


def write_html_entry(out: Path) -> None:
    (out / "boot.js").write_text(BOOT_JS, encoding="utf-8")
    index_path = out / "index.html"
    if index_path.exists():
        existing = index_path.read_text(encoding="utf-8", errors="ignore")
        if MARKER not in existing and OLD_MARKER not in existing:
            print(f"Kept {index_path}: it has no generated-by marker.")
            return
    index_path.write_text(INDEX_HTML, encoding="utf-8")


def main() -> int:
    repo_root = Path(__file__).resolve().parent.parent
    client_dir = repo_root / "meerai-web-client"
    manifest = client_dir / "Cargo.toml"
    args = parse_args(repo_root / "target" / "web")
    out = args.out.resolve()

    env = os.environ.copy()
    cargo = resolve_cargo(env)
    if not env.get("RUSTUP_TOOLCHAIN"):
        active = capture(["rustup", "show", "active-toolchain"])
        if active:
            env["RUSTUP_TOOLCHAIN"] = active.split()[0]

    meta_raw = subprocess.check_output(
        [
            cargo,
            "metadata",
            "--manifest-path",
            str(manifest),
            "--format-version",
            "1",
            "--no-deps",
        ],
        env=env,
        text=True,
    )
    meta = json.loads(meta_raw)
    target_dir = Path(meta["target_directory"])
    workspace_root = Path(meta["workspace_root"])
    bindgen_env = env.copy()

    if args.dev:
        profile = "web-dev"
        build_flags = [
            "--profile",
            "web-dev",
            "--config",
            'profile.web-dev.inherits="dev"',
            "--config",
            "profile.web-dev.debug=0",
            "--config",
            'profile.web-dev.package."*".opt-level=1',
        ]
        run_opt = False
    else:
        profile = "release"
        build_flags = ["--release"]
        run_opt = args.opt
        env.setdefault("CARGO_PROFILE_RELEASE_OPT_LEVEL", "s")
        env.setdefault("CARGO_PROFILE_RELEASE_LTO", "thin")
        env.setdefault("CARGO_PROFILE_RELEASE_CODEGEN_UNITS", "1")
        env.setdefault("CARGO_PROFILE_RELEASE_DEBUG", "0")
        env.setdefault("CARGO_PROFILE_RELEASE_STRIP", "debuginfo")
        home = str(Path.home())
        cargo_home = env.get("CARGO_HOME", str(Path.home() / ".cargo"))
        remap = (
            f"--remap-path-prefix={home}=/home --remap-path-prefix={cargo_home}=/cargo"
        )
        env["RUSTFLAGS"] = f"{env.get('RUSTFLAGS', '')} {remap}".strip()

    artifact = (
        target_dir / "wasm32-unknown-unknown" / profile / "meerai_web_client.wasm"
    )
    started = time.monotonic()

    subprocess.run(
        [
            cargo,
            "build",
            "--manifest-path",
            str(manifest),
            "-p",
            "meerai-web-client",
            "--target",
            "wasm32-unknown-unknown",
            *build_flags,
            "--lib",
        ],
        env=env,
        check=True,
    )
    if not artifact.is_file():
        sys.exit(f"cargo finished but {artifact} is missing.")

    out.mkdir(parents=True, exist_ok=True)
    next_dir = out / ".next"
    if next_dir.exists():
        shutil.rmtree(next_dir)
    next_dir.mkdir(parents=True)

    bindgen_cmd = [
        cargo,
        "run",
        "--manifest-path",
        str(workspace_root / "Cargo.toml"),
        "-p",
        "meerai-web-bindgen",
        "--",
        "--out-dir",
        str(next_dir),
        "--out-name",
        "app",
    ]
    if not args.dev and not args.names:
        bindgen_cmd.append("--remove-name-section")
    bindgen_cmd.append(str(artifact))
    subprocess.run(bindgen_cmd, env=bindgen_env, check=True)

    if run_opt:
        wasm_path = next_dir / "app_bg.wasm"
        opt_path = next_dir / "app_bg.opt.wasm"
        opt_cmd = ["wasm-opt", "-Oz"]
        if args.names:
            opt_cmd.append("-g")
        opt_cmd.extend(
            [
                "--enable-bulk-memory",
                "--enable-nontrapping-float-to-int",
                "--enable-sign-ext",
                "--enable-reference-types",
                "--enable-exception-handling",
                str(wasm_path),
                "-o",
                str(opt_path),
            ]
        )
        subprocess.run(opt_cmd, env=env, check=True)
        opt_path.replace(wasm_path)

    styles = client_dir / "styles" / "app.css"
    if styles.is_file():
        shutil.copy2(styles, next_dir / "styles.css")

    assets_dir = client_dir / "assets"
    required_assets = (
        "logo.svg",
        "favicon.svg",
        "favicon.ico",
        "favicon-16x16.png",
        "favicon-32x32.png",
        "apple-touch-icon.png",
    )
    if not all((assets_dir / name).is_file() for name in required_assets):
        subprocess.run(
            [
                sys.executable,
                str(repo_root / "scripts" / "generate_favicon.py"),
                "--out",
                str(assets_dir),
            ],
            check=True,
        )
    if assets_dir.is_dir():
        for asset in assets_dir.iterdir():
            if asset.is_file():
                shutil.copy2(asset, next_dir / asset.name)

    for stale in out.glob("Inter-*.ttf"):
        stale.unlink(missing_ok=True)

    for entry in next_dir.iterdir():
        dest = out / entry.name
        if entry.is_dir() and dest.exists():
            shutil.rmtree(dest)
        elif dest.is_dir():
            shutil.rmtree(dest)
        entry.replace(dest)
    next_dir.rmdir()

    if not args.no_html:
        write_html_entry(out)

    if not args.dev:
        wasm_file = out / "app_bg.wasm"
        raw = wasm_file.read_bytes()
        gz = gzip.compress(raw, mtime=0)
        print(f"{wasm_file}: {len(raw):,} bytes raw, {len(gz):,} bytes gzip")

    elapsed = int(time.monotonic() - started)
    print(f"Built {profile} in {elapsed} s. Static folder: {out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
